function Show-SystemDiagnostics {Show-Header;Write-Host "DIAGNOSTICO COMPLETO" -ForegroundColor Yellow;try{$os=Get-CimInstance Win32_OperatingSystem;$pc=Get-CimInstance Win32_ComputerSystem;$cpu=Get-CimInstance Win32_Processor|Select-Object -First 1;$gpu=Get-CimInstance Win32_VideoController|Select-Object -First 1;Write-Host "Computador : $($pc.Manufacturer) $($pc.Model)";Write-Host "Windows    : $($os.Caption) (Build $($os.BuildNumber))";Write-Host "CPU        : $($cpu.Name)";Write-Host "RAM        : $([math]::Round($pc.TotalPhysicalMemory/1GB,2)) GB";Write-Host "GPU        : $($gpu.Name)";Write-Host "Uptime     : $([math]::Round(((Get-Date)-$os.LastBootUpTime).TotalHours,1)) horas";Write-Host "";powercfg /getactivescheme;Write-Host "";Get-CimInstance Win32_LogicalDisk -Filter "DriveType=3"|ForEach-Object{Write-Host "$($_.DeviceID) Livre: $([math]::Round($_.FreeSpace/1GB,1)) GB de $([math]::Round($_.Size/1GB,1)) GB"};Write-Log "Diagnostico exibido."}catch{Write-Status "Diagnostico incompleto." Yellow;Write-Log $_.Exception.Message ERROR};Pause-WinOptimizer}